const D = { energy: .6, scale: 1, speed: 1, density: .5, band: .5, grain: .45, hue: 26, x: .5, y: .5, style: 'phase_field', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Directional solidification: an alloy pulled through a thermal gradient. A flat
// front is unstable (Mullins-Sekerka) -- a bump reaches richer liquid and runs
// ahead, surface tension fights back at short wavelength -- which is exactly the
// Kuramoto-Sivashinsky equation:
//        h_t = -A h_xx - B h_xxxx - C (h_x)^2
// A destabilises, B stabilises, C saturates. It selects a cell spacing and then
// stays CHAOTIC forever: cells split, drift and get squeezed out, never settling.
// That deterministic chaos is this piece's anti-convergence guarantee.
//
// The solid keeps the record: the buffer below the front is a space-time plot of
// h, so the trajectories of the cell minima become the intercellular grooves of
// the microstructure, and it scrolls away downward for as long as the alloy is
// pulled. On top of that A drifts (spacing wanders, so cells must split and
// merge) and the pulling rate V drifts (banded microstructure) -- both on
// incommensurate K.t rates.
// ---------------------------------------------------------------------------
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(100, Math.round(BW * height / width));
const N = BW * BH;
const FY = Math.round(BH * 0.32);
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.h = new Float32Array(BW); S.hn = new Float32Array(BW);
  S.M = new Float32Array(N); S.Mb = new Float32Array(N);
  S.init = false; S.seedUsed = null;
}

const sd = P.seed | 0;
function hs3(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
let RR = 0, GG = 0, BB = 0;
function hsv(h, s, v) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i, p2 = v * (1 - s), q = v * (1 - f * s), w = v * (1 - (1 - f) * s);
  if (i === 0) { RR = v; GG = w; BB = p2; } else if (i === 1) { RR = q; GG = v; BB = p2; }
  else if (i === 2) { RR = p2; GG = v; BB = w; } else if (i === 3) { RR = p2; GG = q; BB = v; }
  else if (i === 4) { RR = w; GG = p2; BB = v; } else { RR = v; GG = p2; BB = q; }
}

const h = S.h, hn = S.hn, M = S.M, Mb = S.Mb;

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  for (let i = 0; i < BW; i++) h[i] = (hs3(i, 5, 2) - 0.5) * 0.9;
  M.fill(0); Mb.fill(0.5);
  S.Y = 0;
}

const tt = K.t;

// ---- KS front: A sets the selected cell spacing and drifts, so cells must split/merge ----
const Abase = 0.42 + P.density * 1.85;
const Adr = Abase * (1 + 0.22 * Math.sin(tt * 0.043) + 0.12 * Math.sin(tt * 0.107 + 1.9) + 0.07 * Math.sin(tt * 0.191 + 0.6));
const Bc = 1.0, Cc = 1.0;
const dt = 0.035;
const sub = Math.max(1, Math.min(6, Math.round(2 + P.speed * 2)));
for (let st = 0; st < sub; st++) {
  let mean = 0;
  for (let i = 0; i < BW; i++) {
    const i1 = i > 0 ? i - 1 : BW - 1, i2 = i > 1 ? i - 2 : BW - 2 + i;
    const j1 = i < BW - 1 ? i + 1 : 0, j2 = i < BW - 2 ? i + 2 : i + 2 - BW;
    const hxx = h[i1] - 2 * h[i] + h[j1];
    const hxxxx = h[i2] - 4 * h[i1] + 6 * h[i] - 4 * h[j1] + h[j2];
    const hx = (h[j1] - h[i1]) * 0.5;
    let v = h[i] + dt * (-Adr * hxx - Bc * hxxxx - Cc * hx * hx);
    if (!(v > -40)) v = -40; else if (v > 40) v = 40;
    hn[i] = v; mean += v;
  }
  mean /= BW;
  for (let i = 0; i < BW; i++) h[i] = hn[i] - mean;   // KS drifts; keep the front centred
}

// normalise the front profile for display + recording
let hmin = 1e9, hmax = -1e9;
for (let i = 0; i < BW; i++) { const v = h[i]; if (v < hmin) hmin = v; if (v > hmax) hmax = v; }
const hrng = Math.max(0.6, hmax - hmin);

// ---- pulling rate drifts -> banded microstructure ----
const Vb = (3.0 + P.speed * 6.0) * (1 + P.band * (0.42 * Math.sin(tt * 0.071) + 0.24 * Math.sin(tt * 0.151 + 1.1) + 0.13 * Math.sin(tt * 0.263 + 2.3)));
const V = Math.max(1.2, Vb) * (0.85 + K.swell * 0.2 + A.lowmid * 0.35);
const bandv = Math.max(0, Math.min(1, (V / (3.0 + P.speed * 6.0) - 0.4) * 0.9));

S.Y += V / 60;
let rows = 0;
while (S.Y >= 1 && rows < 8) {
  S.Y -= 1; rows++;
  M.copyWithin((FY + 1) * BW, FY * BW, (BH - 1) * BW);
  Mb.copyWithin((FY + 1) * BW, FY * BW, (BH - 1) * BW);
  const o = FY * BW;
  for (let i = 0; i < BW; i++) {
    const dpt = (hmax - h[i]) / hrng;              // 0 at a cell tip, 1 in the deepest groove
    M[o + i] = dpt;
    Mb[o + i] = bandv;
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const style = P.style;
const hb = P.hue / 360 + (K.section | 0) * 0.023 + Math.sin(tt * 0.017) * 0.018;
const gain = 0.45 + P.energy * 1.1 + A.rms * 0.3;
const gr = P.grain;
const amp = Math.min(BH * 0.11, 3.2 + P.energy * 3.0);
for (let i = 0; i < BW; i++) {
  const fy = FY - ((h[i] - (hmin + hmax) * 0.5) / hrng) * 2 * amp;   // live front profile
  const im = i > 0 ? i - 1 : BW - 1, ip = i < BW - 1 ? i + 1 : 0;
  for (let j = 0; j < BH; j++) {
    const p = j * BW + i;
    const th = (hs3(i, j, 71) - 0.5) * 0.09 * gr;
    let r, gg, b;
    const dfr = j - fy;
    if (dfr < 0) {
      // ---- liquid: thermal gradient + solute boundary layer piled ahead of the front
      const dep = Math.min(1, -dfr / (BH * 0.34));
      const sol = Math.max(0, 1 - (-dfr) * 0.09);          // solute pile-up hugging the front
      const shim = (hs3(i, (j + (tt * 9 | 0)) % BH, 13) - 0.5) * 0.05;
      if (style === 'micrograph') { const v = 0.10 + dep * 0.05 + sol * 0.06 + shim; r = v; gg = v * 0.99; b = v * 0.97; }
      else if (style === 'dic') { const v = 0.46 + sol * 0.05 + shim * 0.5; r = v; gg = v * 0.995; b = v * 1.01; }
      else if (style === 'schematic') { const v = 0.055 + sol * 0.05; r = v * 0.5; gg = v * 0.9; b = v * 1.9; }
      else {
        hsv(hb + 0.52, 0.62 - dep * 0.12, 1);
        const v = (0.09 + dep * 0.05 + sol * 0.10) * (0.7 + gain * 0.4);
        r = RR * v; gg = GG * v; b = BB * v;
      }
    } else {
      // ---- mushy zone then solid: read the space-time record
      const rec = j >= FY ? M[p] : M[FY * BW + i];
      const bnd = j >= FY ? Mb[p] : bandv;
      const mush = Math.max(0, 1 - dfr * 0.20);            // latent-heat glow behind the front
      const groove = Math.pow(rec, 1.35);
      if (style === 'micrograph') {
        // etched longitudinal section: bright cell cores, dark intercellular grooves
        const v = (0.62 - groove * 0.50 + bnd * 0.07) * (0.55 + gain * 0.45);
        r = v * 1.0 + mush * 0.30; gg = v * 0.985 + mush * 0.28; b = v * 0.94 + mush * 0.24;
      } else if (style === 'dic') {
        // Nomarski relief: form from light only, pseudo-3D off the groove gradient
        const gx = (j >= FY ? M[p - (i > 0 ? 1 : 1 - BW)] : rec) - (j >= FY ? M[p + (i < BW - 1 ? 1 : 1 - BW)] : rec);
        const gy = j > FY && j < BH - 1 ? M[p - BW] - M[p + BW] : 0;
        const rel = 0.5 + (gx * 2.6 + gy * 1.1) * (0.6 + gain * 0.7);
        const v = Math.max(0, Math.min(1, rel)) * 0.72 + 0.12 + bnd * 0.04;
        r = v * 1.0 + mush * 0.16; gg = v * 0.99 + mush * 0.16; b = v * 0.96 + mush * 0.14;
      } else if (style === 'schematic') {
        // blueprint: the groove trajectories and the live front, nothing else
        const line = Math.max(0, groove - 0.52) * 2.1;
        const fl = Math.max(0, 1 - Math.abs(dfr) * 0.5);
        r = 0.06 + line * 0.42 * gain + fl * 0.30;
        gg = 0.09 + line * 0.80 * gain + fl * 0.56;
        b = 0.15 + line * 1.0 * gain + fl * 0.74;
      } else {
        // phase_field (default): solid warm, grooves solute-dark, hot mushy zone,
        // pulling-rate bands laid horizontally through the microstructure
        hsv(hb + 0.02 + bnd * 0.05, 0.30 + groove * 0.30, 1);
        const v = (0.30 + (1 - groove) * 0.52 + bnd * 0.09) * (0.55 + gain * 0.5);
        r = RR * v; gg = GG * v; b = BB * v;
        hsv(hb + 0.09, 0.55, 1);
        r += RR * mush * 0.42 * gain; gg += GG * mush * 0.42 * gain; b += BB * mush * 0.42 * gain;
      }
    }
    const o = 4 * p;
    px[o] = Math.max(0, Math.min(255, (r + th) * 255));
    px[o + 1] = Math.max(0, Math.min(255, (gg + th) * 255));
    px[o + 2] = Math.max(0, Math.min(255, (b + th) * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh2 = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh2) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh2);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
